    t162 = tk_sb_line(l0, TK_S(""));
    t163 = tk_sb_line(l0, TK_S("static size_t tk_bump_span(size_t size) { return (size + sizeof(size_t) + 15) & ~(size_t)15; }"));
    t164 = tk_sb_line(l0, TK_S(""));
    t165 = tk_sb_line(l0, TK_S("static size_t *tk_bump_cell(size_t size, int zero) {"));
