    t135 = tk_sb_line(l0, TK_S("// cache, for the next large request: best fit, so a cached block may"));
    t136 = tk_sb_line(l0, TK_S("// serve a smaller request, whose later growth then needs no syscall."));
    t137 = tk_sb_line(l0, TK_S("// The cache holds at most RT_LC_MAX blocks and RT_LC_CAP bytes; past"));
    t138 = tk_sb_line(l0, TK_S("// either bound the oldest blocks go back to the kernel. Cached blocks"));
    t139 = tk_sb_line(l0, TK_S("// are not in use: RS_USED never counts them."));
    t140 = tk_sb_line(l0, TK_S("//"));
    t141 = tk_sb_line(l0, TK_S("// trackc --native inlines the arena bump path for constant sizes"));
