    t153 = tk_sb_line(l0, TK_S("fn rt_page_up(n: i64) -> i64 { return (n + 4095) & (0 - 4096); }"));
    t154 = tk_sb_line(l0, TK_S(""));
    t155 = tk_sb_line(l0, TK_S("// Ask for 2 MiB pages on a mapping big enough to hold one."));
