    t222 = tk_sb_line(l0, TK_S(""));
    t223 = tk_sb_line(l0, TK_S("// The smallest cached mapping of at least `len` bytes, taken out of the"));
    t224 = tk_sb_line(l0, TK_S("// cache; 0 when none is big enough."));
    t225 = tk_sb_line(l0, TK_S("fn rt_lc_take(len: i64) -> i64 {"));
