    t260 = tk_sb_line(l0, TK_S(""));
    t261 = tk_sb_line(l0, TK_S("// Keep the freed mapping `m` for reuse, unmapping the oldest cached"));
    t262 = tk_sb_line(l0, TK_S("// blocks past the cache's bounds (or `m` itself when it alone is past"));
