    t282 = tk_sb_line(l0, TK_S(""));
    t283 = tk_sb_line(l0, TK_S("// Fault in the arena ahead of the bump pointer, past at least `need`."));
    t284 = tk_sb_line(l0, TK_S("// Steps double from 64 KiB to 2 MiB, so small programs do not pay for"));
