    t307 = tk_sb_line(l0, TK_S(""));
    t308 = tk_sb_line(l0, TK_S("fn rt_malloc(size: i64) -> i64 { return rt_block(size, false); }"));
    t309 = tk_sb_line(l0, TK_S(""));
    t310 = tk_sb_line(l0, TK_S("fn rt_free(p: i64) -> i64 {"));
