    t324 = tk_sb_line(l0, TK_S(""));
    t325 = tk_sb_line(l0, TK_S("// Usable bytes of block `p`."));
    t326 = tk_sb_line(l0, TK_S("fn rt_capacity(p: i64) -> i64 {"));
