    t361 = tk_sb_line(l0, TK_S(""));
    t362 = tk_sb_line(l0, TK_S("// ------------------------------------------------------- raw memory ops"));
    t363 = tk_sb_line(l0, TK_S(""));
    t364 = tk_sb_line(l0, TK_S("// x86-64 allows unaligned word access, so copy words whatever the"));
    t365 = tk_sb_line(l0, TK_S("// alignment, four at a time in the bulk."));
    t366 = tk_sb_line(l0, TK_S("fn rt_copy(dst: i64, src: i64, n: i64) -> i64 {"));
