    t149 = tk_sb_line(l0, TK_S("        p = p + 1;"));
    t150 = tk_sb_line(l0, TK_S("    }"));
    t151 = tk_sb_line(l0, TK_S("    if load8(p) == 0 {"));
    t152 = tk_sb_line(l0, TK_S("        return 0;"));
    t153 = tk_sb_line(l0, TK_S("    }"));
    t154 = tk_sb_line(l0, TK_S("    while load8(p) != 0 {"));
