    t160 = tk_sb_line(l0, TK_S("    return 1;"));
    t161 = tk_sb_line(l0, TK_S("}"));
    t162 = tk_sb_line(l0, TK_S(""));
    t163 = tk_sb_line(l0, TK_S("fn int_to_str(val: i64) -> i64 { return rt_dup(rt_fmt_int(val)); }"));
    t164 = tk_sb_line(l0, TK_S(""));
    t165 = tk_sb_line(l0, TK_S("fn str_starts_with(s: i64, prefix: i64) -> bool {"));
    t166 = tk_sb_line(l0, TK_S("    if s == 0 || prefix == 0 {"));
    t167 = tk_sb_line(l0, TK_S("        return false;"));
    t168 = tk_sb_line(l0, TK_S("    }"));
    t169 = tk_sb_line(l0, TK_S("    return rt_match_at(s, 0, prefix);"));
    t170 = tk_sb_line(l0, TK_S("}"));
    t171 = tk_sb_line(l0, TK_S(""));
    t172 = tk_sb_line(l0, TK_S("fn str_ends_with(s: i64, suffix: i64) -> bool {"));
    t173 = tk_sb_line(l0, TK_S("    if s == 0 || suffix == 0 {"));
    t174 = tk_sb_line(l0, TK_S("        return false;"));
    t175 = tk_sb_line(l0, TK_S("    }"));
    t176 = tk_sb_line(l0, TK_S("    let ls = rt_strlen(s);"));
    t177 = tk_sb_line(l0, TK_S("    let lp = rt_strlen(suffix);"));
