    t180 = tk_sb_line(l0, TK_S("    }"));
    t181 = tk_sb_line(l0, TK_S("    return rt_match_at(s, ls - lp, suffix);"));
    t182 = tk_sb_line(l0, TK_S("}"));
    t183 = tk_sb_line(l0, TK_S(""));
    t184 = tk_sb_line(l0, TK_S("fn str_substr(s: i64, start: i64, len: i64) -> i64 {"));
    t185 = tk_sb_line(l0, TK_S("    if s == 0 || start < 0 || len <= 0 {"));
    t186 = tk_sb_line(l0, TK_S("        return rt_dup_n(\"\", 0);"));
    t187 = tk_sb_line(l0, TK_S("    }"));
    t188 = tk_sb_line(l0, TK_S("    let avail = rt_strnlen(s, start + len);"));
    t189 = tk_sb_line(l0, TK_S("    if start >= avail {"));
    t190 = tk_sb_line(l0, TK_S("        return rt_dup_n(\"\", 0);"));
    t191 = tk_sb_line(l0, TK_S("    }"));
    t192 = tk_sb_line(l0, TK_S("    return rt_dup_n(s + start, avail - start);"));
    t193 = tk_sb_line(l0, TK_S("}"));
    t194 = tk_sb_line(l0, TK_S(""));
    t195 = tk_sb_line(l0, TK_S("fn str_trim(s: i64) -> i64 {"));
    t196 = tk_sb_line(l0, TK_S("    if s == 0 {"));
    t197 = tk_sb_line(l0, TK_S("        return rt_dup_n(\"\", 0);"));
    t198 = tk_sb_line(l0, TK_S("    }"));
    t199 = tk_sb_line(l0, TK_S("    let mut p = s;"));
    t200 = tk_sb_line(l0, TK_S("    while load8(p) != 0 && rt_is_space(load8(p)) {"));
    t201 = tk_sb_line(l0, TK_S("        p = p + 1;"));
    t202 = tk_sb_line(l0, TK_S("    }"));
    t203 = tk_sb_line(l0, TK_S("    let mut len = rt_strlen(p);"));
    t204 = tk_sb_line(l0, TK_S("    while len > 0 && rt_is_space(load8(p + len - 1)) {"));
