    t206 = tk_sb_line(l0, TK_S("    }"));
    t207 = tk_sb_line(l0, TK_S("    return rt_dup_n(p, len);"));
    t208 = tk_sb_line(l0, TK_S("}"));
    t209 = tk_sb_line(l0, TK_S(""));
    t210 = tk_sb_line(l0, TK_S("fn str_char_at(s: i64, idx: i64) -> i64 {"));
    t211 = tk_sb_line(l0, TK_S("    if s == 0 || idx < 0 {"));
    t212 = tk_sb_line(l0, TK_S("        return 0;"));
    t213 = tk_sb_line(l0, TK_S("    }"));
    t214 = tk_sb_line(l0, TK_S("    if rt_strnlen(s, idx + 1) <= idx {"));
