    t216 = tk_sb_line(l0, TK_S("    }"));
    t217 = tk_sb_line(l0, TK_S("    return load8(s + idx);"));
    t218 = tk_sb_line(l0, TK_S("}"));
    t219 = tk_sb_line(l0, TK_S(""));
    t220 = tk_sb_line(l0, TK_S("// Copy a string's bytes into a collection for O(1) bounds-checked access."));
    t221 = tk_sb_line(l0, TK_S("fn track_str_bytes(s: i64) -> i64 {"));
    t222 = tk_sb_line(l0, TK_S("    let mut len: i64 = 0;"));
    t223 = tk_sb_line(l0, TK_S("    if s != 0 {"));
