    t225 = tk_sb_line(l0, TK_S("    }"));
    t226 = tk_sb_line(l0, TK_S("    let out = track_i64_collection_new(len + 1);"));
    t227 = tk_sb_line(l0, TK_S("    let data = load64(out);"));
    t228 = tk_sb_line(l0, TK_S("    let mut i: i64 = 0;"));
    t229 = tk_sb_line(l0, TK_S("    while i < len {"));
    t230 = tk_sb_line(l0, TK_S("        store64(data + 8 * i, load8(s + i));"));
    t231 = tk_sb_line(l0, TK_S("        i = i + 1;"));
    t232 = tk_sb_line(l0, TK_S("    }"));
    t233 = tk_sb_line(l0, TK_S("    store64(out + 8, len);"));
    t234 = tk_sb_line(l0, TK_S("    return out;"));
    t235 = tk_sb_line(l0, TK_S("}"));
    t236 = tk_sb_line(l0, TK_S(""));
    t237 = tk_sb_line(l0, TK_S("fn char_is_digit(ch: i64) -> bool { return rt_is_digit(ch); }"));
    t238 = tk_sb_line(l0, TK_S("fn char_is_alpha(ch: i64) -> bool { return rt_is_alpha(ch); }"));
    t239 = tk_sb_line(l0, TK_S("fn char_is_alphanumeric(ch: i64) -> bool { return rt_is_alpha(ch) || rt_is_digit(ch); }"));
