    t245 = tk_sb_line(l0, TK_S("    }"));
    t246 = tk_sb_line(l0, TK_S("    return ch;"));
    t247 = tk_sb_line(l0, TK_S("}"));
    t248 = tk_sb_line(l0, TK_S(""));
    t249 = tk_sb_line(l0, TK_S("fn char_to_lower(ch: i64) -> i64 {"));
