    t301 = tk_sb_line(l0, TK_S(""));
    t302 = tk_sb_line(l0, TK_S("// inet_pton for dotted-quad IPv4; -1 when malformed."));
    t303 = tk_sb_line(l0, TK_S("fn rt_parse_ipv4(s: i64) -> i64 {"));
    t304 = tk_sb_line(l0, TK_S("    let mut addr: i64 = 0;"));
