    t331 = tk_sb_line(l0, TK_S("        } else {"));
    t332 = tk_sb_line(l0, TK_S("            return -1;"));
    t333 = tk_sb_line(l0, TK_S("        }"));
    t334 = tk_sb_line(l0, TK_S("        i = i + 1;"));
